 debug("mipi_dsi_dcs_write: channel={}, cmd=0x{x}, len={}", .{ channel, cmd, len });
 if (cmd == MIPI_DSI_DCS_SHORT_WRITE) { assert(len == 1); }
 if (cmd == MIPI_DSI_DCS_SHORT_WRITE_PARAM) { assert(len == 2); }

